import React from 'react';

export const StatCard = ({ title, value, icon, trend, color }) => {
  // Color mapping
  const colorMap = {
    blue: { bg: 'bg-blue-900/20', text: 'text-blue-400', border: 'border-blue-500/20' },
    green: { bg: 'bg-green-900/20', text: 'text-green-400', border: 'border-green-500/20' },
    purple: { bg: 'bg-purple-900/20', text: 'text-purple-400', border: 'border-purple-500/20' },
    orange: { bg: 'bg-orange-900/20', text: 'text-orange-400', border: 'border-orange-500/20' },
    red: { bg: 'bg-red-900/20', text: 'text-red-400', border: 'border-red-500/20' },
  };

  const { bg, text, border } = colorMap[color] || colorMap.blue;
  const isPositiveTrend = trend.startsWith('+');
  const trendColorClass = isPositiveTrend ? 'text-green-500' : 'text-red-500';
  const trendIcon = isPositiveTrend ? '↑' : '↓';

  return (
    <div className="bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700/50 p-4">
      <div className="flex items-start">
        <div className="flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-lg">
          <span className={`${text} text-xl`}>{icon}</span>
        </div>
        <div className="flex-1 ml-3">
          <p className="text-sm font-medium text-gray-400">{title}</p>
          <p className="mt-1 text-2xl font-bold text-white">{value}</p>
          {trend && (
            <p className="mt-1 flex items-center gap-1 text-sm">
              <span className={trendColorClass}>
                {trendIcon} {trend}
              </span>
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useAuth } from '../hooks/useAuth';
import { useNavigate } from 'react-router-dom';
import { Link } from 'react-router-dom';

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Simulate API call
    setTimeout(() => {
      if (formData.email && formData.password) {
        login({ email: formData.email, name: formData.email.split('@')[0] });
        navigate('/dashboard');
      } else {
        setError('Please fill in all fields');
        setLoading(false);
      }
    }, 1000);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900">
      <div className="w-full max-w-md space-y-8">
        <div>
          <h2 className="text-3xl font-bold text-center text-white">
            Welcome Back
          </h2>
          <p className="text-center text-gray-400">
            Sign in to your account to continue
          </p>
        </div>
        <form className="space-y-6" onSubmit={handleSubmit}>
          <div>
            <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
              Email Address
            </label>
            <input
              id="email"
              type="email"
              required
              className="block w-full rounded-md bg-gray-800 border border-gray-700 px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
              Password
            </label>
            <input
              id="password"
              type="password"
              required
              className="block w-full rounded-md bg-gray-800 border border-gray-700 px-3 py-2 text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              value={formData.password}
              onChange={(e) => setFormData({ ...formData, password: e.target.value })}
            />
          </div>

          {error && (
            <p className="text-red-500 text-center text-sm">{error}</p>
          )}

          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <input
                id="remember"
                type="checkbox"
                className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              />
              <label htmlFor="remember" className="ml-2 block text-sm text-gray-300">
                Remember me
              </label>
            </div>
            <Link
              to="/forgot-password"
              className="text-sm text-blue-500 hover:text-blue-400"
            >
              Forgot password?
            </Link>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-flex justify-center items-center w-full px-4 py-2 text-sm font-medium transition-colors duration-200 transform bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? (
              <>
                <span className="mr-2">Signing in...</span>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z"></path>
                </svg>
              </>
            ) : (
              'Sign In'
            )}
          </button>
        </form>

        <p className="text-center text-xs text-gray-500">
          Don't have an account?{' '}
          <Link to="/register" className="font-medium text-blue-500 hover:text-blue-400">
            Sign Up
          </Link>
        </p>
      </div>
    </div>
  );
}

