:root {
  /* Color Palette - Dark Theme with Accents */
  --bg-darkest: #050505;
  --bg-darker: #0a0a0a;
  --bg-dark: #1a1a1a;
  --bg-medium: #2d2d2d;
  --bg-light: #3a3a3a;

