/* Hero Section with 3D Background */
class HeroSection {
  constructor() {
    this.container = null;
    this.scene = null;
    this.camera = null;
    this.renderer = null;
    this.mesh = null;
  }

  init(containerElement, title, subtitle) {
    this.container = containerElement;
    this.createTitle(title);
    this.createSubtitle(subtitle);
    this.create3DBackground();
    this.animate();
  }

  createTitle(title) {
    const titleElement = document.createElement('h1');
    titleElement.className = 'text-4xl md:text-5xl lg:text-6xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-cyan-400';
    titleElement.textContent = title;
    this.container.appendChild(titleElement);
  }

  createSubtitle(subtitle) {
    const subtitleElement = document.createElement('p');
    subtitleElement.className = 'text-xl md:text-2xl max-w-xl mx-auto text-gray-300';
    subtitleElement.textContent = subtitle;
    this.container.appendChild(subtitleElement);
  }

  create3DBackground() {
    // Create container for the canvas
    const canvasContainer = document.createElement('div');
    canvasContainer.className = 'absolute inset-0 -z-10';
    this.container.insertBefore(canvasContainer, this.container.firstChild);

    // Initialize Three.js scene
    this.scene = new THREE.Scene();

    // Set up camera
    this.camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    this.camera.position.z = 5;

    // Set up renderer
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    canvasContainer.appendChild(this.renderer.domElement);

    // Add lighting
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    this.scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(10, 20, 10);
    this.scene.add(directionalLight);

    // Create a 3D shape (server rack inspired)
    const geometry = new THREE.BoxGeometry(2, 1, 1.5);
    const material = new THREE.MeshStandardMaterial({
      color: 0x0ea5e9,
      metalness: 0.2,
      roughness: 0.5
    });
    this.mesh = new THREE.Mesh(geometry, material);
    this.mesh.position.set(0, 0, 0);
    this.mesh.rotation.set(0, Math.PI / 4, 0);
    this.scene.add(this.mesh);

    // Add floating particles
    const particlesGeometry = new THREE.BufferGeometry();
    const particlesCount = 100;
    const positions = new Float32Array(particlesCount * 3);

    for (let i = 0; i < particlesCount * 3; i++) {
      positions[i] = (Math.random() - 0.5) * 10;
    }

    particlesGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

    const particlesMaterial = new THREE.PointsMaterial({
      size: 0.02,
      color: 0x0ea5e9,
      transparent: true,
      opacity: 0.6
    });

    const particles = new THREE.Points(particlesGeometry, particlesMaterial);
    this.scene.add(particles);

    // Handle window resize
    window.addEventListener('resize', () => {
      this.camera.aspect = window.innerWidth / window.innerHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(window.innerWidth, window.innerHeight);
    });
  }

  animate() {
    requestAnimationFrame(() => this.animate());

    // Rotate the mesh
    this.mesh.rotation.y += 0.005;
    this.mesh.rotation.x += 0.002;

    // Render
    this.renderer.render(this.scene, this.camera);
  }
}

// Initialize when DOM is loaded
const heroSection = new HeroSession();

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    // Find hero section containers and initialize them
    const heroContainers = document.querySelectorAll('[data-hero]');
    heroContainers.forEach(container => {
      const title = container.getAttribute('data-title') || 'Default Title';
      const subtitle = container.getAttribute('data-subtitle') || 'Default Subtitle';
      heroSection.init(container, title, subtitle);
    });
  });
} else {
  // DOM already loaded
  const heroContainers = document.querySelectorAll('[data-hero]');
  heroContainers.forEach(container => {
    const title = container.getAttribute('data-title') || 'Default Title';
    const subtitle = container.getAttribute('data-subtitle') || 'Default Subtitle';
    heroSection.init(container, title, subtitle);
  });
}

// Export for use in other modules
window.heroSection = heroSection;

