// Simple Router for SPA
class Router {
  constructor() {
    this.routes = {}; // path => { component: Function, isProtected: boolean }
    this.currentPath = window.location.pathname;
    this.auth = {
      user: null,
      token: localStorage.getItem('token') || null,
      login: (userData) => {
        // Simulate login
        this.auth.user = {
          id: '1',
          name: userData.email.split('@')[0],
          email: userData.email,
          role: 'admin' // Simplified
        };
        this.auth.token = 'fake-token';
        localStorage.setItem('token', this.auth.token);
        return Promise.resolve();
      },
      logout: () => {
        this.auth.user = null;
        this.auth.token = null;
        localStorage.removeItem('token');
        return Promise.resolve();
      }
    };

    // Bind event listeners
    window.addEventListener('popstate', () => {
      this.navigate(window.location.pathname);
    });

    // Initial navigation
    this.navigate(this.currentPath);
  }

  // Add a route
  add(path, component, isProtected = false) {
    this.routes[path] = { component, isProtected };
    return this;
  }

  // Navigate to a path
  navigate(path) {
    // Update URL without reloading
    window.history.pushState({}, '', path);
    this.currentPath = path;
    this.render();
  }

  // Get current route
  getCurrentRoute() {
    return this.routes[this.currentPath] || null;
  }

  // Check if user is authenticated
  isAuthenticated() {
    return !!this.auth.user;
  }

  // Render the current route
  render() {
    const route = this.getCurrentRoute();
    const appEl = document.getElementById('app');

    if (!appEl) {
      console.error('No root element with id "app" found');
      return;
    }

    if (!route) {
      // 404 - Not Found
      appEl.innerHTML = '<div class="p-8 text-center text-white">404 - Page Not Found</div>';
      return;
    }

    // Check if route requires authentication
    if (route.isProtected && !this.isAuthenticated()) {
      // Redirect to login
      this.navigate('/login');
      return;
    }

    // Clear the app element and render the component
    appEl.innerHTML = '';
    const componentInstance = route.component(this.auth);
    if (typeof componentInstance === 'string') {
      appEl.innerHTML = componentInstance;
    } else if (componentInstance instanceof HTMLElement) {
      appEl.appendChild(componentInstance);
    } else if (typeof componentInstance.render === 'function') {
      // If it's a component with a render method
      appEl.appendChild(componentInstance.render());
    } else {
      console.error('Component must return a string, HTMLElement, or have a render method');
    }
  }
}

// Create a singleton router instance
const router = new Router();

// Export for use in other modules
window.router = router;

