  }

  attachEventListeners() {
    if (!this.container) return;

    // User menu dropdown
    const userMenuButton = this.container.querySelector('#user-menu-button');
    const userMenuDropdown = this.container.querySelector('#user-menu-dropdown');
    const logoutButton = this.container.querySelector('#logout-button');

    if (userMenuButton && userMenuDropdown) {
      userMenuButton.addEventListener('click', (e) => {
        e.stopPropagation();
        userMenuDropdown.classList.toggle('hidden');
      });

      // Close dropdown when clicking outside
      document.addEventListener('click', (e) => {
        if (!userMenuButton.contains(e.target) && !userMenuDropdown.contains(e.target)) {
          userMenuDropdown.classList.add('hidden');
        }
      });
    }

    if (logoutButton && this.logoutCallback) {
      logoutButton.addEventListener('click', (e) => {
        e.preventDefault();
        this.logoutCallback();
      });
    }
  }
}

