// Stat Card Component
export function createStatCard(props) {
  // Create the container
  const element = document.createElement('div');
  element.className = 'bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700/50 p-4';

  // Determine colors based on prop
  const colorMap = {
    blue: { bg: 'bg-blue-900/20', text: 'text-blue-400', border: 'border-blue-500/20' },
    green: { bg: 'bg-green-900/20', text: 'text-green-400', border: 'border-green-500/20' },
    purple: { bg: 'bg-purple-900/20', text: 'text-purple-400', border: 'border-purple-500/20' },
    orange: { bg: 'bg-orange-900/20', text: 'text-orange-400', border: 'border-orange-500/20' },
    red: { bg: 'bg-red-900/20', text: 'text-red-400', border: 'border-red-500/20' }
  };

  const { bg, text, border } = colorMap[props.color] || colorMap.blue;
  const isPositiveTrend = props.trend && props.trend.startsWith('+');
  const trendColorClass = isPositiveTrend ? 'text-green-500' : 'text-red-500';
  const trendIcon = isPositiveTrend ? '↑' : '↓';

  // Build the HTML content
  element.innerHTML = `
    <div class="flex items-start">
      <div class="flex-shrink-0 w-10 h-10 flex items-center justify-center rounded-lg ${bg}">
        <span class="${text} text-xl">${props.icon}</span>
      </div>
      <div class="flex-1 ml-3">
        <p class="text-sm font-medium text-gray-400">${props.title}</p>
        <p class="mt-1 text-2xl font-bold text-white">${props.value}</p>
        ${props.trend ? `<p class="mt-1 flex items-center gap-1 text-sm">
          <span class="${trendColorClass}">
            ${trendIcon} ${props.trend}
          </span>
        </p>` : ''}
      </div>
    </div>
  `;

  return element;
}

