                        <a href="#" className="block px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">Settings</a>
                        <button onClick=${() => onLogout()} className="block w-full text-left px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">
                          Logout
                        </button>
                      </div>
                    </div>
                  </div>
                </>
              `}
            </>
          `}
        </div>
      </div>
    `;

    // Add event listener for the user dropdown
    const userButton = element.querySelector('button');
    const dropdown = element.querySelector('.absolute');
    if (userButton && dropdown) {
      userButton.addEventListener('click', (e) => {
        e.stopPropagation();
        dropdown.classList.toggle('hidden');
      });

      // Close dropdown when clicking outside
      document.addEventListener('click', (e) => {
        if (!element.contains(e.target)) {
          dropdown.classList.add('hidden');
        }
      });
    }

    return element;
  }
}

