// Navbar Component
export class Navbar {
  constructor() {
    this.container = null;
    this.user = null; // Will be set by the auth system
    this.logoutCallback = null;
  }

  init(containerElement, user = null, logoutCallback = null) {
    this.container = containerElement;
    this.user = user;
    this.logoutCallback = logoutCallback;
    this.render();
    this.attachEventListeners();
  }

  render() {
    if (!this.container) return;

    const isAdmin = this.user && this.user.role === 'admin';
    const isStaff = this.user && ['admin', 'rental_manager', 'sales_rep', 'operations_staff', 'accounting'].includes(this.user.role);
    const isCustomer = this.user && this.user.role === 'customer';

