                      ? 'bg-gray-800 text-white'
                      : 'text-gray-300 hover:text-white hover:bg-gray-800'
                    } flex items-center gap-1 px-3 py-2 rounded-md">
                      ${item.icon}
                      <span>${item.name}</span>
                    </a>
                  </li>
                `).join('')}
              </ul>
            </div>
          </div>
          <div class="flex items-center space-x-4">
            ${!this.user ? `
              <a href="/login" class="btn-primary px-4 py-2 rounded-md text-sm font-medium">Login</a>
            ` : `
              <>
                ${isCustomer && `
                  <>
                    <a href="/customer-portal" class="flex items-center gap-2 text-gray-300 hover:text-white">
                      <span>🏪</span>
                      <span>Customer Portal</span>
                    </a>
                  </>
                `}
                {!isCustomer && `
                  <>
                    <div class="relative">
                      <button
                        id="user-menu-button"
                        class="flex items-center gap-2 text-gray-300 hover:text-white"
                      >
                        <span>👤</span>
                        <span>${this.user?.name || 'User'}</span>
                        <svg class="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                        </svg>
                      </button>
                      <div id="user-menu-dropdown" class="absolute right-0 mt-2 w-48 bg-gray-800/80 backdrop-blur-sm border border-gray-700 rounded-md shadow-lg z-20 hidden">
                        <div class="py-2">
                          <a href="#" class="block px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">Profile</a>
                          <a href="#" class="block px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">Settings</a>
                          <button id="logout-button" class="block w-full text-left px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">
                            Logout
                          </button>
                        </div>
                      </div>
                    </>
                  `}
              </>
            `}
          </div>
        </div>
      </nav>
    `;
  }

  attachEventListeners() {
    if (!this.container) return;

    // User menu dropdown
    const userMenuButton = this.container.querySelector('#user-menu-button');
    const userMenuDropdown = this.container.querySelector('#user-menu-dropdown');
    const logoutButton = this.container.querySelector('#logout-button');

    if (userMenuButton && userMenuDropdown) {
      userMenuButton.addEventListener('click', (e) => {
        e.stopPropagation();
        userMenuDropdown.classList.toggle('hidden');
      });

      // Close dropdown when clicking outside
      document.addEventListener('click', (e) => {
        if (!userMenuButton.contains(e.target) && !userMenuDropdown.contains(e.target)) {
          userMenuDropdown.classList.add('hidden');
        }
      });
    }

    if (logoutButton && this.logoutCallback) {
      logoutButton.addEventListener('click', (e) => {
        e.preventDefault();
        this.logoutCallback();
      });
    }
  }
}

